    {

           using var activity =  StartCallActivity("SearchChatAffiliateProgramAsync", typeof(SearchChatAffiliateProgram).FullName ?? "SearchChatAffiliateProgramAsync");

           try
           {
             return client.SearchChatAffiliateProgramAsync(username, referrer);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
